'::jsonb) loop if not exists(select 1 from public.ea_records where id=c->>'id' and (data=c->'before' or data=c->'after')) then raise exception 'Election changed after label audit: %',c->>'id'; end if; update public.ea_records set data=c->'after',updated=now() where id=c->>'id' and data=c->'before'; end loop; if exists(select 1 from public.ea_country_parties t where id=(p->>'id')::uuid and to_jsonb(t)<>p and to_jsonb(t)<>jsonb_set(p,'{archived}','true'::jsonb)) then raise exception 'Unused profile changed after audit'; end if; update public.ea_country_parties set archived=true where id=(p->>'id')::uuid; end $fix$; commit;
